local module = {}

--[=[
	将用户注册到悟空服务器
	@param userData any? -- 用户序列化后的数据， 如果为空则创建新用户容器
	@return WuKongFacade.Type -- 用户门面
]=]
function module.RegisterUser(wukongServer: IWuKongServer, userId: number, userData: any?): IWuKongFacade
	local container = nil
	if userData then
		container = wukongServer:DeserializeWuKongContainer(userId, userData)
	else
		-- 创建新用户数据
		container = wukongServer:CreateWuKongContainer(userId)
	end

	-- 注册到悟空
	local facade = wukongServer:Register(container)
	return facade
end

--[=[
	将用户从悟空服务器注销
	@param userId
	@return {}? -- 返回空,说明用户未在悟空服务器注册,否则返回用户序列化后的数据,供入库
]=]
function module.UnregisterUser(wukongServer: IWuKongServer, userId: number): {}?
	if not wukongServer:HasFacade(userId) then
		return
	end

	local facade = wukongServer:GetFacade(userId)

	local container = facade:GetContainer()

	facade:Dispose()

	wukongServer:UnRegister(userId)

	return wukongServer:SerializeWuKongContainer(container)
end

return module
